sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading) {
    if (isLoading || newValue == '') {
        //Display the validation Status pre upload
        g_form.setValue('validation_status', 'pending_upload'); //Pending Upload
        //Clear summary if no upload
        g_form.clearValue('validation_summary');
        return;
    }

    var currentTradeMarket = g_form.getDisplayValue('owning_business'); // Get this from another form field if needed
    var uploadType = g_form.getValue('upload_type'); // upload type

    //g_form.setValue('validation_progress', 'step3'); //Validation in Progress
    var checkIfEmptyFile = new GlideAjax('x_hsb11_hsbc_mss_o.MSSCustodyBulkFileUpload');
    checkIfEmptyFile.addParam('sysparm_name', 'checkBulkValidationStatus');
    checkIfEmptyFile.addParam('sysparm_market', currentTradeMarket);
    checkIfEmptyFile.getXMLAnswer(checkifemptyRec);

    //Running GlideAjax
    if (newValue != '') {
        g_form.setValue('validation_status', 'validation_in_progress'); //Upload Successful
        g_form.showFieldMsg('upload_file', 'Please wait until the validation is completed...', 'info', true);

    }
    //Running GlideAjax

    function checkifemptyRec(response) {

        g_form.addInfoMessage('Summary ' + response);

        var dataSummary = '';
        var errorDetails = response.split("/");
        var result = errorDetails[0];
        var summaryTotalCount = errorDetails[1] ? errorDetails[1] : 'NA';
        var summaryErrorRecords = errorDetails[2] ? errorDetails[2] : 'NA';
        var summaryValidRecords = errorDetails[3] ? errorDetails[3] : 'NA';
        var clientValidationSummary = response ? response : 'NA';


        try {

            // MSSCUSTODY 6700 - Handle file type or size validation errors
            if ((response == "Invalid file type") || (response == "File size exceeded")) {
                // g_form.addErrorMessage(result); // Display error message
                g_form.setValue('validation_status', 'validation_failed'); // Set validation status to failed

                if (response == "Invalid file type") {
                    dataSummary = 'Validation failed. The file uploaded must be of type .xlsx.';
                } else if (response == "File size exceeded") {
                    dataSummary = 'Validation failed. The file uploaded exceeds maximum limit of 10MB';
                } else {
                    dataSummary = 'Validation failed. The file uploaded may be invalid/corrupt.';
                }
                // return;
            } else if (result == 'Limit Exceeded') { //more than 500 records
                dataSummary = 'Validation failed. The file contains more than 500 records of allowed limit';
                g_form.setValue('validation_status', 'validation_failed'); //Validation Failed
                g_form.addErrorMessage(' The uuploaded file contains more than 500 records. Please upload a file with 500 or less than 500 trades');

            } else if (result == "Validation Failed") {

                spModal.open({
                    title: 'Validation Errors',
                    widget: 'bulk_file_upload_error_details', // Your widget's sys_id or widget ID
                    widgetInput: {
                        tradeMarket: currentTradeMarket,
                        uploadtype: uploadType,
                        validationSummary: clientValidationSummary
                    },

                    size: 'lg' // large modal

                }).then(function(result) {
                    // Handle modal close if needed
                    //console.log('Modal closed, result:', result);
                });


                //updating status

                dataSummary = 'Validation Failed. The data uploaded contains more than 10% of error records';
                g_form.setValue('validation_status', 'validation_failed'); //Validation Failed

                //updating status

            } else if (result == "No Errors" || result == "Validation Successful") {

                if (result == "No Errors") {
                    dataSummary = 'Validation successful. The data uploaded contains no error records';
                }

                if (result == "Validation Successful") {
                    dataSummary = 'Validation successful. The data uploaded contains less than 10% of error records';
                }
                g_form.setValue('validation_status', 'validation_successful'); //Validation Successful

            } else if (result == "No records Found") {

                dataSummary = 'Validation failed. The file uploaded seems to be empty. Please review';

                //  g_form.setValue('validation_progress', 'step5'); //Validation Failed

                spModal.open({
                    title: 'Empty File Alert!',
                    widget: 'bulk_file_upload_empty_alert', // Your widget's sys_id or widget ID
                    widgetInput: {
                        //tradeMarket: currentTradeMarket
                        //attachmentSysId: attachmentSysId,
                    },

                    size: 'lg' // large modal

                }).then(function(result) {
                    // Handle modal close if needed
                    // console.log('Modal closed, result:', result);
                });

                g_form.setValue('validation_status', 'validation_failed'); //Validation Failed


            } else {
                //error handling for a  corrupted file
                dataSummary = 'Validation failed. The file uploaded seems to be corrupted. Please review';
                g_form.setValue('validation_status', 'validation_failed'); //Validation Failed //exception handling if any other response received

            }

        } catch (ex) {
            g_form.addErrorMessage('Error from CLient ' + ex);
        }



        //validation Summary
        var htmlContent = '<p style="color: black;">Total Records : <strong>' + summaryTotalCount + '</strong></p>' +
            '<p style="color: black;">Error Records : <strong style="color: red;">' + summaryErrorRecords + '</strong></p>' + // Label black, value red
            '<p style="color: black;">Valid Records : <strong style="color: green;">' + summaryValidRecords + '</strong></p>' + // Label black, value green
            '<p style="color: black;">Note:&nbsp;' + dataSummary + '</p>'; // Note label not bold, overall black

        g_form.setValue('validation_summary', htmlContent);
        //validation Summary

        g_form.hideFieldMsg('upload_file', 'Please wait until the validation is completed...');
        g_form.showFieldMsg('upload_file', 'Validation has been completed', 'info', true);



    }
}
